on conflict (id_categorie) do update set nom_categorie = excluded.nom_categorie;

on conflict (id_produit) do update set nom_produit = excluded.nom_produit, description = excluded.description, prix = excluded.prix, stock = excluded.stock, image = excluded.image, id_categorie = excluded.id_categorie;

select setval(pg_get_serial_sequence('public.produit', 'id_produit'), (select max(id_produit) from public.produit));
select setval(pg_get_serial_sequence('public.categorie', 'id_categorie'), (select max(id_categorie) from public.categorie));